const ALIASES = {
  'magic-button': 'quiz-game',
  'gamer': 'portfolio',
  'space-blog': 'space-story',
  'store': 'cyber-store',
  'delivery': 'cyber-store',
  'pizza': 'cyber-store',
}

export function getTemplate(id) {
  const targetId = ALIASES[id] || id
  return TEMPLATES.find((t) => t.id === targetId) ?? TEMPLATES[0]
}
